def grip_y(x):
    t = (x - 15.5) / 65.0
    return 10.5 + 48.0 * t*t * (1.0-t)**2 - thumb_depth(x)/2.0

def thumb_depth(x):
    if not 28.0 <= x <= 68.0:
        return 0.0
    u = (x - 28.0) / 40.0
    return 24.0 * u*u * (1.0-u)**2

def clip_polygon(polygon, axis, value, direction):
    result = []
    if not polygon:
        return result
    previous = polygon[-1]
    previous_inside = direction * (previous[axis] - value) >= 0.0
    for current in polygon:
        inside = direction * (current[axis] - value) >= 0.0
        if inside != previous_inside:
            fraction = (value - previous[axis]) / (current[axis] - previous[axis])
            result.append(tuple(previous[i] + fraction*(current[i]-previous[i]) for i in range(len(current))))
        if inside:
            result.append(tuple(current))
        previous, previous_inside = current, inside
    return result

def distance_to_segment(point, a, b):
    delta = [b[i]-a[i] for i in range(len(point))]
    squared = sum(value*value for value in delta)
    fraction = 0.0 if squared == 0.0 else max(0.0, min(1.0, sum((point[i]-a[i])*delta[i] for i in range(len(point)))/squared))
    return math.sqrt(sum((a[i]+fraction*delta[i]-point[i])**2 for i in range(len(point))))

def polygon_contains(loop, point):
    inside = False
    for a, b in zip(loop, loop[1:]+loop[:1]):
        if (a[1] > point[1]) != (b[1] > point[1]) and point[0] < a[0] + (point[1]-a[1])*(b[0]-a[0])/(b[1]-a[1]):
            inside = not inside
    return inside

def polygon_radial_bounds(polygon, center):
    projected = [(float(p[0]), float(p[1])) for p in polygon]
    if not projected:
        raise RuntimeError('Cannot measure an empty projected polygon')
    minimum = 0.0 if polygon_contains(projected, center) else min(distance_to_segment(center, a, b) for a,b in zip(projected, projected[1:]+projected[:1]))
    maximum = max(math.dist(center, p) for p in projected)
    if not math.isfinite(minimum) or not math.isfinite(maximum):
        raise RuntimeError('Non-finite radial geometry')
    return minimum, maximum

def slab_radial_bounds(points, triangles, center, lower, upper, near_radius=None, open_caps=False):
    minimum, maximum, count = float('inf'), 0.0, 0
    for indices in triangles:
        polygon = [tuple(float(v) for v in points[index]) for index in indices]
        if max(p[2] for p in polygon) < lower or min(p[2] for p in polygon) > upper:
            continue
        if open_caps and (max(p[2] for p in polygon)<=lower or min(p[2] for p in polygon)>=upper):
            continue
        polygon = clip_polygon(clip_polygon(polygon, 2, lower, 1.0), 2, upper, -1.0)
        if not polygon:
            continue
        low, high = polygon_radial_bounds(polygon, center)
        if near_radius is not None and low >= near_radius:
            continue
        minimum, maximum, count = min(minimum, low), max(maximum, high), count+1
    if not count:
        raise RuntimeError('Required radial slab surface is missing')
    return {'minimum_radius_mm': minimum, 'maximum_radius_mm': maximum, 'triangle_pieces': count}

def point_in_solid(points, triangles, point):
    # Oriented solid angle also covers complete containment, which surface/cylinder
    # intersection alone cannot detect. Topology/winding are independently gated.
    if any(point[i] < min(p[i] for p in points) or point[i] > max(p[i] for p in points) for i in range(3)):
        return False
    total = 0.0
    for indices in triangles:
        a,b,c = [tuple(float(points[index][i])-point[i] for i in range(3)) for index in indices]
        lengths = [math.sqrt(sum(value*value for value in vertex)) for vertex in (a,b,c)]
        if min(lengths) <= 1e-12:
            raise RuntimeError('Containment point lies on the measured surface')
        numerator = a[0]*(b[1]*c[2]-b[2]*c[1])+a[1]*(b[2]*c[0]-b[0]*c[2])+a[2]*(b[0]*c[1]-b[1]*c[0])
        dot_ab = sum(a[i]*b[i] for i in range(3))
        dot_bc = sum(b[i]*c[i] for i in range(3))
        dot_ca = sum(c[i]*a[i] for i in range(3))
        denominator = lengths[0]*lengths[1]*lengths[2]+dot_ab*lengths[2]+dot_bc*lengths[0]+dot_ca*lengths[1]
        total += 2.0*math.atan2(numerator, denominator)
    if not math.isfinite(total):
        raise RuntimeError('Non-finite containment observation')
    if abs(total) < 1e-5:
        return False
    if abs(abs(total)-4.0*math.pi) < 1e-5:
        return True
    raise RuntimeError('Ambiguous solid-angle containment; preserve the failed subject')

def cylinder_occupancy(points, triangles, center, radius, lower, upper):
    penetrations, minimum = 0, None
    for indices in triangles:
        polygon = [tuple(float(v) for v in points[index]) for index in indices]
        # The volume is open at both caps. A coplanar mounting face is contact,
        # not material above the pad. Any noncoplanar intrusion is retained.
        if max(p[2] for p in polygon) <= lower or min(p[2] for p in polygon) >= upper:
            continue
        polygon = clip_polygon(clip_polygon(polygon, 2, lower, 1.0), 2, upper, -1.0)
        if not polygon:
            continue
        low, high = polygon_radial_bounds(polygon, center)
        minimum = low if minimum is None else min(minimum, low)
        penetrations += int(low < radius)
    contained = point_in_solid(points, triangles, (center[0], center[1], (lower+upper)/2.0))
