def geometric_triangle_area(vertices):
    if len(vertices) != 3:
        raise RuntimeError('The exact acceptance mesh must be explicitly triangulated')
    a, b, c = vertices
    u = [float(b[i]) - float(a[i]) for i in range(3)]
    v = [float(c[i]) - float(a[i]) for i in range(3)]
    cross = [u[1]*v[2] - u[2]*v[1], u[2]*v[0] - u[0]*v[2], u[0]*v[1] - u[1]*v[0]]
    return math.sqrt(sum(value * value for value in cross)) / 2.0

def inspect_geometry(obj):
    obj.data.calc_loop_triangles()
    if not 0 < len(obj.data.loop_triangles) <= 80000:
        raise RuntimeError('Triangle limit exceeded before geometry analysis')
    points = [v.co.copy() for v in obj.data.vertices]
    if not points or any(not math.isfinite(c) for v in points for c in v):
        raise RuntimeError('Empty or non-finite geometry')
    lo = [min(v[i] for v in points) for i in range(3)]
    hi = [max(v[i] for v in points) for i in range(3)]
    bm = bmesh.new()
    bm.from_mesh(obj.data)
    bm.normal_update()
    bm.verts.index_update()
    winding = 0
    for edge in bm.edges:
        if len(edge.link_faces) == 2:
            directions = []
            for face in edge.link_faces:
                loop = next(loop for loop in face.loops if loop.edge == edge)
                directions.append((loop.vert.index, loop.link_loop_next.vert.index))
            winding += int(directions[0] == directions[1])
    remaining = set(bm.verts)
    components = 0
    while remaining:
        components += 1
        pending = [remaining.pop()]
        while pending:
            vertex = pending.pop()
            for edge in vertex.link_edges:
                other = edge.other_vert(vertex)
                if other in remaining:
                    remaining.remove(other)
                    pending.append(other)
    triangle_indices = [tuple(triangle.vertices) for triangle in obj.data.loop_triangles]
    tree = BVHTree.FromPolygons(points, triangle_indices, all_triangles=True, epsilon=0.0)
    overlap_pairs = sum(1 for a, b in tree.overlap(tree) if a < b and not any(index in triangle_indices[b] for index in triangle_indices[a]))
    result = {
        'feature_measurement_version': 'printed02-freecad-repair/4',
        'nominal_grip_mesh_fidelity': nominal_grip_mesh_fidelity(),
        'root_mesh_fidelity': root_mesh_fidelity(),
        'nonadjacent_triangle_overlap_pairs': overlap_pairs,
        'vertices': len(bm.verts), 'edges': len(bm.edges),
        'triangles': len(obj.data.loop_triangles),
        'non_manifold_edges': sum(not edge.is_manifold for edge in bm.edges),
        'boundary_edges': sum(edge.is_boundary for edge in bm.edges),
        'wire_edges': sum(edge.is_wire for edge in bm.edges),
        'degenerate_faces': sum(geometric_triangle_area([v.co for v in face.verts]) <= 1e-10 for face in bm.faces),
        'native_bmesh_degenerate_area_observations': sum(face.calc_area() <= 1e-10 for face in bm.faces),
        'degenerate_triangles': sum(geometric_triangle_area([points[index] for index in t.vertices]) <= 1e-10 for t in obj.data.loop_triangles),
        'winding_conflicts': winding, 'connected_components': components,
        'euler_characteristic': len(bm.verts) - len(bm.edges) + len(bm.faces),
        'signed_volume_mm3': bm.calc_volume(signed=True),
        'bounds_min_mm': lo, 'bounds_max_mm': hi,
        'dimensions_mm': [hi[i] - lo[i] for i in range(3)],
    }
    bm.free()
    central = []
    for triangle in obj.data.loop_triangles:
        polygon = [points[index] for index in triangle.vertices]
        for plane, direction in ((15.5, 1.0), (80.5, -1.0)):
            clipped = []
            if polygon:
                previous = polygon[-1]
                previous_inside = direction * (previous.x - plane) >= 0
                for current in polygon:
                    inside = direction * (current.x - plane) >= 0
                    if inside != previous_inside:
                        fraction = (plane - previous.x) / (current.x - previous.x)
                        clipped.append(previous + fraction * (current - previous))
                    if inside:
                        clipped.append(current)
                    previous, previous_inside = current, inside
            polygon = clipped
        central.extend(vertex.z for vertex in polygon)
    if not central:
        raise RuntimeError('No actual geometry in the required central span')
    result['central_span_mm'] = [15.5, 80.5]
    result['central_slab_surface_z_mm'] = [min(central), max(central)]
    pads = []
    holes = []
    for cx in (0.0, 96.0):
        pad_points = [v for v in points if cx - 9.00001 <= v.x <= cx + 9.00001 and v.z <= 5.00001]
        if not pad_points:
            raise RuntimeError('Mounting-pad sample is absent')
        contact_area = 0.0
        for triangle in obj.data.loop_triangles:
            vertices = [points[index] for index in triangle.vertices]
            if all(abs(v.z) <= 1e-5 and abs(v.x - cx) <= 9.00001 for v in vertices):
                contact_area += (vertices[1] - vertices[0]).cross(vertices[2] - vertices[0]).length / 2.0
        pads.append({
            'center_x_mm': cx,
            'bounded_pad_region_min_mm': [min(v[i] for v in pad_points) for i in range(3)],
            'bounded_pad_region_max_mm': [max(v[i] for v in pad_points) for i in range(3)],
            'flat_z0_contact_area_mm2': contact_area,
        })
        section_hits, distances, continuous_diameters = radial_section_hits(points, [triangle.vertices for triangle in obj.data.loop_triangles], 2.5, cx)
        hits = [Vector(point) for point in section_hits]
        center = sum(((hits[i] + hits[i + 64]) * 0.5 for i in range(64)), Vector()) / 64
        obstructions = 0
        for i in range(17):
            radius = 0.0 if i == 16 else 2.249
            angle = 2.0 * math.pi * i / 16
            hit, location, normal, index = obj.ray_cast(Vector((cx + radius * math.cos(angle), radius * math.sin(angle), -1.0)), Vector((0.0, 0.0, 1.0)), distance=40.0)
            obstructions += int(hit)
        measured_bore = bore_observation(points, triangle_indices, cx)
        washer = cylinder_occupancy(points, triangle_indices, (cx, 0.0), 5.0, 5.0, 34.0)
        holes.append({
            'observed_midplane_center_mm': list(center),
            'sampled_midplane_diameter_min_max_mm': [2 * min(distances), 2 * max(distances)],
            'continuous_midplane_diameter_min_max_mm': continuous_diameters,
            'axial_obstructions_of_17': obstructions,
            'complete_bore': measured_bore,
            'provisional_washer_reserve': washer,
        })
    result['pads'] = pads
    result['holes'] = holes
    result['observed_hole_center_separation_mm'] = (Vector(holes[1]['observed_midplane_center_mm']) - Vector(holes[0]['observed_midplane_center_mm'])).length
    result['grip_sections'] = [grip_section(points, triangle_indices, x) for x in (15.5, 22.0, 27.5, 28.0, 38.0, 48.0, 58.0, 68.0, 68.5, 74.0, 80.5)]
    result['root_sections'] = root_sections(points, triangle_indices)
    result['remaining_feature_review'] = ['Native R1 inventory and continuity are separate construction evidence; finite sections do not certify every touched surface.', 'The complete sampled root meridians do not establish unsampled upper-transition curvatures or hardware fit.', 'The complete provisional10mm cylinder occupancy check is not a measurement of actual washer OD/thickness, seating or tool approach.', 'Inspect exact mesh-to-sketch intent; manifold topology and native construction success alone are insufficient.']
    return result

def require_pad(pad, center_x):
    eps = 0.00005
    if any(abs(v-e)>eps for v,e in zip(pad['bounded_pad_region_min_mm'],(center_x-9.0,-6.2,0.0))) or any(abs(v-e)>eps for v,e in zip(pad['bounded_pad_region_max_mm'],(center_x+9.0,17.8,5.0))) or pad['flat_z0_contact_area_mm2']<200.0:
        raise RuntimeError('Flat nominal18x24x5mm mounting pad not preserved')

def require_geometry(values):
    eps = 0.00005  # Numerical representation bound, not a manufacturing allowance.
    if any(values[key] for key in ('non_manifold_edges', 'boundary_edges', 'wire_edges', 'degenerate_faces', 'degenerate_triangles', 'winding_conflicts', 'nonadjacent_triangle_overlap_pairs')):
        raise RuntimeError('Closed consistent topology was not preserved: ' + str(values))
    if values['connected_components'] != 1 or values['euler_characteristic'] != -2 or values['signed_volume_mm3'] <= 0:
        raise RuntimeError('Expected one positive-volume solid with exactly two through-hole handles')
    if not 0 < values['triangles'] <= 80000:
        raise RuntimeError('Triangle limit exceeded')
    lo, hi = values['bounds_min_mm'], values['bounds_max_mm']
    if any(d > limit + eps for d, limit in zip(values['dimensions_mm'], (118.0, 28.0, 34.0))) or lo[1] < -18.0 or abs(lo[2]) > eps or hi[2] > 34.0 + eps:
        raise RuntimeError('Original envelope, mounting plane or label keepout violated')
    if values['central_slab_surface_z_mm'][0] < 25.0 - eps:
        raise RuntimeError('The complete central65mm surface violates finger clearance')
    for pad, cx in zip(values['pads'], (0.0, 96.0)):
        require_pad(pad, cx)
    for hole, cx in zip(values['holes'], (0.0, 96.0)):
        require_bore(hole['complete_bore'])
        if hole['provisional_washer_reserve']['occupied']:
            raise RuntimeError('Actual material occupies the declared provisional10mm washer reserve; hardware acceptance remains pending')
        if hole['continuous_midplane_diameter_min_max_mm'][0] < 4.5 - eps or hole['continuous_midplane_diameter_min_max_mm'][1] > 4.503 or hole['axial_obstructions_of_17'] or abs(hole['observed_midplane_center_mm'][0] - cx) > eps or abs(hole['observed_midplane_center_mm'][1]) > eps or hole['sampled_midplane_diameter_min_max_mm'][0] < 4.5 - eps or hole['sampled_midplane_diameter_min_max_mm'][1] > 4.503:
            raise RuntimeError('Required M4 clearance bore not preserved')
    if abs(values['observed_hole_center_separation_mm'] - 96.0) > eps:
        raise RuntimeError('Bolt-center separation changed')
    for section in values['grip_sections']:
        require_grip(section)
    for root in values['root_sections']:
        require_root(root)

